import fs from 'node:fs/promises';import assert from 'node:assert/strict';import crypto from 'node:crypto';
import {volumeFeatures,FILTERS,S} from './research-short-squeeze-volume-20261107.mjs';
const d='data/research/short-squeeze-volume-20261107',read=async p=>JSON.parse(await fs.readFile(p)),x=await read(d+'/results.json'),f=await read(d+'/fetch-complete.json'),cache=new Map(),hash=b=>crypto.createHash('sha256').update(b).digest('hex'),near=(a,b)=>assert.ok(Math.abs(a-b)<1e-8);
async function raw(symbol){if(!cache.has(symbol)){const b=await fs.readFile(d+'/raw/'+encodeURIComponent(symbol)+'-data.json');assert.equal(hash(b),f.rawHashes[symbol]);cache.set(symbol,JSON.parse(b));}return cache.get(symbol);}
const btc=await raw('BTCUSDT');let volumes=0,sweeps=0,nonfutureChecks=0;
for(const r of x.records){const a=await raw(r.symbol),bars=a.price.filter(b=>+b[6]<r.decisionAt).slice(-23);if(r.features.status==='OK'){let old=0,quote=0,buy=0;for(let j=0;j<20;j++)old+=+bars[j][7];for(let j=20;j<23;j++){quote+=+bars[j][7];buy+=+bars[j][10];}near(r.features.volume15m,quote/(old/20*3));near(r.features.sellPct,(quote-buy)/quote*100);assert.ok(+bars.at(-1)[6]+5000<=r.availableAt);volumes++;}
if(r.model.status==='OK'){const z=r.model.zone,path=a.mark.filter(b=>+b[0]>=r.entryAt&&+b[0]<r.entryAt+96*S);assert.equal(path.length,96);const low=Math.min(...path.map(b=>+b[3]));assert.equal(r.model.touch,low<=z.high);assert.equal(r.model.swept,low<=z.low);const waiting=a.mark.filter(b=>+b[0]>=r.model.asOf&&+b[0]<r.entryAt);assert.ok(waiting.every(b=>+b[3]>z.high));assert.ok(r.model.asOf<=r.decisionAt-S);sweeps++;}
if(nonfutureChecks<12){const modified=structuredClone(a);for(const b of modified.price)if(+b[0]>=r.decisionAt){b[7]=String(+b[7]*100);b[10]='0';}assert.deepEqual(volumeFeatures(modified,r,btc),volumeFeatures(a,r,btc));nonfutureChecks++;}}
const eligible=x.records.filter(r=>r.features.status==='OK'&&r.trade.status==='OK'&&r.excursion.status==='OK');
for(const [k,fn]of Object.entries(FILTERS)){const selected=eligible.filter(r=>fn(r.features)),s=x.groups[k].all;assert.equal(s.n,selected.length);assert.equal(s.n+x.groups[k].rejected.n,eligible.length);if(selected.length){near(s.meanRoe,selected.reduce((a,r)=>a+r.trade.netRoe,0)/selected.length);near(s.winPct,100*selected.filter(r=>r.trade.netRoe>0).length/selected.length);}const z=selected.filter(r=>r.model.status==='OK');assert.equal(s.model.n,z.length);if(z.length)near(s.model.sweepPct,100*z.filter(r=>r.model.swept).length/z.length);}
const runtime=Object.fromEntries(await Promise.all(Object.entries(x.manifest.runtimeHashes).map(async([p,h])=>[p,hash(await fs.readFile(p))===h])));
const out={status:'PASS',rawHashes:cache.size,volumesRecomputed:volumes,sweepsRecomputed:sweeps,futureVolumeInvariance:nonfutureChecks,thresholdPartitionsAndStats:true,runtimeHashesUnchanged:runtime};assert.ok(Object.values(runtime).every(Boolean));await fs.writeFile(d+'/independent-validation.json',JSON.stringify(out,null,2));console.log(JSON.stringify(out));

